def flatten(d: dict) -> dict:
    result = {}
    for k, v in d.items():
        if isinstance(v, dict):
            # Recursively flatten nested dictionaries (though the prompt implies one level, 
            # a robust solution handles deeper nesting if needed, but for strict one-level flattening, 
            # we just iterate over the inner keys)
            for sub_k, sub_v in v.items():
                new_key = f"{k}.{sub_k}"
                result[new_key] = sub_v
        else:
            result[k] = v
    return result
