def dedupe(rows: list[dict], key: str) -> list[dict]:
    seen_keys = set()
    result = []
    for row in rows:
        if key not in row or row[key] not in seen_keys:
            if key in row:
                seen_keys.add(row[key])
            result.append(row)
        elif key in row and row[key] in seen_keys:
            # Duplicate found, skip (keep the first one)
            pass
        else:
            # Row is missing 'key', always keep it
            result.append(row)
    return result
