def parse_money(s: str) -> float | None:
    if not s or isinstance(s, str) and s.strip() in ("", "n/a"):
        return None

    # Strip leading '$' if present
    cleaned_s = s.lstrip('$')

    # Remove thousands separators (commas)
    cleaned_s = cleaned_s.replace(",", "")

    try:
        return float(cleaned_s)
    except ValueError:
        return None
